using System.Drawing.Printing;
using HammerTrackPro2.Models;

namespace HammerTrackPro2.Services;

public sealed class AuctionSettlementPrinter
{
    internal const string DocumentHeading="END-OF-NIGHT REPORT";
    public PrintDocument CreateDocument(AuctionSettlementReport report,Auction auction){ArgumentNullException.ThrowIfNull(report);ArgumentNullException.ThrowIfNull(auction);var document=new PrintDocument{DocumentName=$"Auction Settlement {report.AuctionNumber}"};document.PrintPage+=(_,e)=>Draw(e.Graphics??throw new InvalidOperationException("The printer did not provide a drawing surface."),e.MarginBounds,report,auction);return document;}
    internal static void Draw(Graphics graphics,Rectangle bounds,AuctionSettlementReport report,Auction auction)
    {
        using var heading=new Font("Segoe UI",9,FontStyle.Bold);using var body=new Font("Segoe UI",8.5F);using var total=new Font("Segoe UI",11,FontStyle.Bold);using var small=new Font("Segoe UI",7.5F);using var navyBrush=new SolidBrush(PrintBranding.Navy);using var whiteBrush=new SolidBrush(Color.White);using var right=new StringFormat{Alignment=StringAlignment.Far};using var pen=new Pen(Color.FromArgb(190,200,210));
        var y=PrintBranding.DrawHeader(graphics,bounds,auction,DocumentHeading,$"Auction {report.AuctionNumber}");graphics.DrawString(report.AuctionName,heading,navyBrush,bounds.Left,y);var details=$"Auction date: {auction.AuctionDate:d}"+(string.IsNullOrWhiteSpace(auction.Location)?string.Empty:$"   Location: {auction.Location}");graphics.DrawString(details,body,Brushes.Black,bounds.Left,y+20);graphics.DrawString($"Prepared: {DateTime.Now:g}",body,Brushes.Black,new RectangleF(bounds.Right-210,y,210,18),right);y+=48;
        PrintBranding.DrawSectionTitle(graphics,"BUYER REVENUE",new Rectangle(bounds.Left,y,bounds.Width,26));y+=34;DrawPair(graphics,body,bounds,ref y,"Total hammer sales",report.HammerSales,"Buyer invoice total",report.InvoiceTotal);DrawPair(graphics,body,bounds,ref y,"Buyer premiums",report.BuyerPremiums,"Buyer payments received",report.InvoiceAmountPaid);DrawPair(graphics,body,bounds,ref y,"Card processing fees",report.CreditCardFees,"Buyer balance unpaid",report.InvoiceBalanceUnpaid);DrawPair(graphics,body,bounds,ref y,"Sales tax collected",report.SalesTaxCollected,string.Empty,0);y+=8;
        PrintBranding.DrawSectionTitle(graphics,"SELLER & OPERATING EXPENSES",new Rectangle(bounds.Left,y,bounds.Width,26));y+=34;DrawPair(graphics,body,bounds,ref y,"Seller gross sales",report.ConsignorGrossSales,"Seller payouts",report.ConsignorPayouts);DrawPair(graphics,body,bounds,ref y,"Seller commissions",report.ConsignorCommissions,"Staff/operating payments",report.StaffPayments);DrawPair(graphics,body,bounds,ref y,"Buyer purchase offsets",report.PurchaseBalanceOffsets,string.Empty,0);y+=8;
        using(var fill=new SolidBrush(PrintBranding.Navy)){graphics.FillRectangle(fill,bounds.Left,y,bounds.Width,42);}graphics.DrawString("NET CASH MOVEMENT",total,whiteBrush,bounds.Left+12,y+11);graphics.DrawString(report.NetCashMovement.ToString("C2"),total,new SolidBrush(PrintBranding.Gold),new RectangleF(bounds.Right-180,y+11,165,22),right);y+=54;
        PrintBranding.DrawSectionTitle(graphics,"STAFF & OPERATING PAYMENT LEDGER",new Rectangle(bounds.Left,y,bounds.Width,26));y+=30;graphics.FillRectangle(navyBrush,bounds.Left,y,bounds.Width,23);graphics.DrawString("DATE",small,whiteBrush,bounds.Left+6,y+5);graphics.DrawString("CATEGORY",small,whiteBrush,bounds.Left+105,y+5);graphics.DrawString("PAYEE / REFERENCE",small,whiteBrush,bounds.Left+205,y+5);graphics.DrawString("METHOD",small,whiteBrush,bounds.Right-190,y+5);graphics.DrawString("AMOUNT",small,whiteBrush,new RectangleF(bounds.Right-95,y+5,85,15),right);y+=26;
        if(report.StaffLedger.Count==0){graphics.DrawString("No staff or operating payments recorded.",body,Brushes.Gray,bounds.Left+6,y);y+=22;}else foreach(var payment in report.StaffLedger.Take(10)){var payee=payment.Payee+(string.IsNullOrWhiteSpace(payment.Notes)?string.Empty:$" - {payment.Notes}");if(!string.IsNullOrWhiteSpace(payment.VoidReason))payee+=$" [VOID: {payment.VoidReason}]";graphics.DrawString(payment.PaidUtc.ToLocalTime().ToString("g"),small,Brushes.Black,bounds.Left+6,y);graphics.DrawString(payment.Category,small,Brushes.Black,bounds.Left+105,y);graphics.DrawString(payee,small,Brushes.Black,new RectangleF(bounds.Left+205,y,bounds.Width-410,17));graphics.DrawString(payment.Method,small,Brushes.Black,bounds.Right-190,y);graphics.DrawString(payment.Amount.ToString("C2"),small,Brushes.Black,new RectangleF(bounds.Right-95,y,85,15),right);y+=19;graphics.DrawLine(pen,bounds.Left,y-2,bounds.Right,y-2);}
        if(report.StaffLedger.Count>10){graphics.DrawString($"{report.StaffLedger.Count-10} additional ledger entr{(report.StaffLedger.Count-10==1?"y":"ies")} available in HammerTrack Pro.",small,Brushes.Gray,bounds.Left+6,y);y+=19;}
        y=Math.Min(bounds.Bottom-82,y+24);graphics.DrawLine(pen,bounds.Left,y,bounds.Left+230,y);graphics.DrawLine(pen,bounds.Right-230,y,bounds.Right,y);graphics.DrawString("Prepared by",small,Brushes.Gray,bounds.Left,y+4);graphics.DrawString("Reviewed by",small,Brushes.Gray,bounds.Right-230,y+4);graphics.DrawString("Generated by HammerTrack Pro",small,Brushes.Gray,bounds.Left,bounds.Bottom-14);
    }
    private static void DrawPair(Graphics graphics,Font font,Rectangle bounds,ref int y,string leftLabel,decimal leftValue,string rightLabel,decimal rightValue){using var right=new StringFormat{Alignment=StringAlignment.Far};var half=bounds.Width/2;graphics.DrawString(leftLabel,font,Brushes.Black,bounds.Left+8,y);graphics.DrawString(leftValue.ToString("C2"),font,Brushes.Black,new RectangleF(bounds.Left+half-110,y,95,18),right);if(!string.IsNullOrWhiteSpace(rightLabel)){graphics.DrawString(rightLabel,font,Brushes.Black,bounds.Left+half+8,y);graphics.DrawString(rightValue.ToString("C2"),font,Brushes.Black,new RectangleF(bounds.Right-105,y,95,18),right);}y+=21;}
}
